local a={}a.CFG={degPerCell=3,tickEvery=10,labelEvery=30,tickCh="|"}local b={[0]="N",[90]="E",[180]="S",[270]="W"}local function c(d)return math.floor(d+0.5)end;function a.norm360(e)local f=e%360;if f<0 then f=f+360 end;return f end;function a.signedDelta(g,h)return(g-h+180)%360-180 end;function a.isOnHeading(i,j,k)if type(i)~="number"or type(j)~="number"then return false end;return math.abs(a.signedDelta(i,j))<(k or 1)end;function a.lubberCol(l)return math.ceil(l/2)end;function a.lubberLabel(m)if type(m)~="number"then return"---"end;return string.format("%03d",c(a.norm360(m))%360)end;local function n(o,p,q)for r=1,#q do local s=p+r-1;if s>=1 and s<=#o then o[s]=q:sub(r,r)end end end;function a.bugCol(t,m,l,u)u=u or a.CFG;if type(t)~="number"or type(m)~="number"or type(l)~="number"or l<1 then return nil end;local p=a.lubberCol(l)+c(a.signedDelta(t,m)/u.degPerCell)if p<1 or p>l then return nil end;return p end;function a.row(m,l,u)u=u or a.CFG;if type(l)~="number"or l<1 then return""end;if type(m)~="number"then return string.rep(" ",l)end;local o={}for r=1,l do o[r]=" "end;local v=a.lubberCol(l)local w=math.floor(l/2)*u.degPerCell+u.labelEvery;local x=c(m/u.tickEvery)*u.tickEvery;for i=x-w,x+w,u.tickEvery do local p=v+c(a.signedDelta(i,m)/u.degPerCell)n(o,p,u.tickCh)end;local y=c(m/u.labelEvery)*u.labelEvery;for i=y-w,y+w,u.labelEvery do local z=a.norm360(i)local A=b[z]or string.format("%02d",c(z/10)%36)local p=v+c(a.signedDelta(i,m)/u.degPerCell)n(o,p-math.floor(#A/2),A)end;return table.concat(o)end;return a